script:
var $ = function (s) { return document.querySelector(s) }
function cpuSeries() {
  var h = dsh.history('host')
  var out = []
  for (var i = 1; i < h.length; i++) {
    var b0 = h[i - 1].value.cpu, b1 = h[i].value.cpu
    if (b1[1] > b0[1]) out.push((b1[0] - b0[0]) / (b1[1] - b0[1]))
  }
  return out
}
function tone(f) { return f > 0.9 ? 'danger' : f > 0.75 ? 'warn' : 'ok' }
dsh.onData(function (data) {
  var r = data.sources.host
  if (!r || !r.ok) {
    $('#cpu').textContent = '—'
    $('#cpu-foot').textContent = ''
    $('#cpu-spark').innerHTML = ''
    $('#rows').innerHTML = dsh.ui.alert(r && r.error ? r.error : '等待数据')
    return
  }
  var v = r.value
  var series = cpuSeries()
  var now = series.length ? series[series.length - 1] : null
  $('#cpu').innerHTML = now === null ? '—' : dsh.fmt.number(now * 100, 1) + '<span class="pad-unit">%</span>'
  $('#cpu').style.color = now === null ? '' : dsh.tone(now)
  $('#cpu-foot').textContent = '更新于 ' + dsh.fmt.ago(r.at) + ' · ' + v.cores + ' 核'
  $('#cpu-spark').innerHTML = dsh.chart.sparkline(series.map(function (x) { return x * 100 }), { width: 280, height: 28, min: 0, max: 100 })
  var memUsed = v.mem[0] ? v.mem[1] / v.mem[0] : 0
  var diskUsed = v.disk[0] ? v.disk[1] / v.disk[0] : 0
  $('#rows').innerHTML = dsh.ui.list([
    { name: '内存', value: dsh.fmt.percent(memUsed), meter: memUsed, tone: tone(memUsed) },
    { name: '磁盘 /', value: dsh.fmt.percent(diskUsed), meter: diskUsed, tone: tone(diskUsed) },
    { name: '负载', value: v.load[0].toFixed(2), tone: tone(v.load[0] / v.cores), foot: v.load[1].toFixed(2) + ' / ' + v.load[2].toFixed(2) + ' · 已运行 ' + dsh.fmt.duration(v.uptime) }
  ])
})
